func testCarregamentoToManyAddOpDDVDocumentoVendas(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Carregamento
	var b, c, d, e DocumentoVenda

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, carregamentoDBTypes, false, strmangle.SetComplement(carregamentoPrimaryKeyColumns, carregamentoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*DocumentoVenda{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, documentoVendaDBTypes, false, strmangle.SetComplement(documentoVendaPrimaryKeyColumns, documentoVendaColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*DocumentoVenda{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddDDVDocumentoVendas(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if first.R.CarCarregamentos[0] != &a {
			t.Error("relationship was not added properly to the slice")
		}
		if second.R.CarCarregamentos[0] != &a {
			t.Error("relationship was not added properly to the slice")
		}

		if a.R.DDVDocumentoVendas[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.DDVDocumentoVendas[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.DDVDocumentoVendas().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

